// ─── CSS (variables.js + GlobalStyle.js + all component styles) ────────────
const FONT_FACES = `
  @font-face {
    font-family: 'Calibre';
    src: url('data:font/woff2;base64,') format('woff2'), url('data:font/woff;base64,') format('woff');
    font-weight: 400; font-style: normal; font-display: auto;
  }
  @font-face {
    font-family: 'Calibre';
    src: url('data:font/woff2;base64,') format('woff2'), url('data:font/woff;base64,') format('woff');
    font-weight: 500; font-style: normal; font-display: auto;
  }
  @font-face {
    font-family: 'Calibre';
    src: url('data:font/woff2;base64,') format('woff2'), url('data:font/woff;base64,') format('woff');
    font-weight: 600; font-style: normal; font-display: auto;
  }
  @font-face {
    font-family: 'SF Mono';
    src: url('data:font/woff2;base64,') format('woff2'), url('data:font/woff;base64,') format('woff');
    font-weight: 400; font-style: normal; font-display: auto;
  }
  @font-face {
    font-family: 'SF Mono';
    src: url('data:font/woff2;base64,') format('woff2'), url('data:font/woff;base64,') format('woff');
    font-weight: 600; font-style: normal; font-display: auto;
  }
`;

const BASE_CSS = `
  :root {
    --dark-navy: #FAF9F6;
    --navy: #FAF9F6;
    --light-navy: #F0EEE9;
    --lightest-navy: #E8E5DF;
    --navy-shadow: rgba(46,46,46,0.15);
    --dark-slate: #2E2E2E;
    --slate: #2E2E2E;
    --light-slate: #444444;
    --lightest-slate: #2E2E2E;
    --white: #FAF9F6;
    --green: #FF3861;
    --green-tint: rgba(255,56,97,0.1);

    --font-sans: 'Calibre','Inter','San Francisco','SF Pro Text',-apple-system,system-ui,sans-serif;
    --font-mono: 'SF Mono','Fira Code','Fira Mono','Roboto Mono',monospace;

    --fz-xxs: 12px; --fz-xs: 13px; --fz-sm: 14px; --fz-md: 16px;
    --fz-lg: 18px;  --fz-xl: 20px; --fz-xxl: 22px; --fz-heading: 32px;

    --border-radius: 8px;
    --nav-height: 100px;
    --nav-scroll-height: 70px;
    --tab-height: 42px;
    --tab-width: 120px;

    --easing: cubic-bezier(0.645,0.045,0.355,1);
    --transition: all 0.25s cubic-bezier(0.645,0.045,0.355,1);
    --hamburger-width: 30px;
    --ham-before: top 0.1s ease-in 0.25s, opacity 0.1s ease-in;
    --ham-before-active: top 0.1s ease-out, opacity 0.1s ease-out 0.12s;
    --ham-after: bottom 0.1s ease-in 0.25s, transform 0.22s cubic-bezier(0.55,0.055,0.675,0.19);
    --ham-after-active: bottom 0.1s ease-out, transform 0.22s cubic-bezier(0.215,0.61,0.355,1) 0.12s;
  }

  *, *::before, *::after { box-sizing: border-box; }

  html {
    box-sizing: border-box; width: 100%; scroll-behavior: smooth;
    scrollbar-width: thin; scrollbar-color: var(--dark-slate) var(--navy);
  }
  ::-webkit-scrollbar { width: 12px; }
  ::-webkit-scrollbar-track { background: var(--navy); }
  ::-webkit-scrollbar-thumb { background-color: var(--dark-slate); border: 3px solid var(--navy); border-radius: 10px; }
  ::selection { background-color: var(--lightest-navy); color: var(--lightest-slate); }

  body {
    margin: 0; width: 100%; min-height: 100%; overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
    background-color: var(--navy); color: var(--slate);
    font-family: var(--font-sans); font-size: var(--fz-xl); line-height: 1.3;
  }
  body.hidden { overflow: hidden; }

  h1,h2,h4,h5,h6 { margin: 0 0 10px; font-weight: 600; color: var(--slate); line-height: 1.1; }
  h3 { margin: 0 0 10px; font-weight: 600; color: var(--light-slate); line-height: 1.1; }
  .big-heading    { margin: 0; font-size: clamp(40px,8vw,80px); }
  .medium-heading { margin: 0; font-size: clamp(40px,8vw,60px); }

  .numbered-heading {
    display: flex; align-items: center; position: relative;
    margin: 10px 0 40px; width: 100%;
    font-size: clamp(26px,5vw,var(--fz-heading)); white-space: nowrap; color: var(--slate);
  }
  .numbered-heading::before {
    position: relative; bottom: 4px;
    counter-increment: section;
    content: '0' counter(section) '.';
    margin-right: 10px; color: var(--green);
    font-family: var(--font-mono);
    font-size: clamp(var(--fz-md),3vw,var(--fz-xl)); font-weight: 400;
  }
  .numbered-heading::after {
    content: ''; display: block; position: relative; top: -5px;
    width: 300px; height: 1px; margin-left: 20px; background-color: var(--lightest-navy); flex-shrink: 1;
  }

  .numbered-heading.overline::before, .numbered-heading.overline::after { content: none; display: none; }
  #featured .numbered-heading::after { display: none; }
  p { margin: 0 0 15px; }
  p:last-child, p:last-of-type { margin: 0; }

  a { display: inline-block; text-decoration: none; text-decoration-skip-ink: auto; color: inherit; position: relative; transition: var(--transition); }
  a:hover, a:focus { color: var(--green); }

  a.inline-link { color: var(--green); }
  a.inline-link::after { content: ''; display: block; width: 0; height: 1px; position: relative; bottom: 0.37em; background-color: var(--green); opacity: 0.5; transition: var(--transition); }
  a.inline-link:hover::after { width: 100%; }

  button { cursor: pointer; border: 0; border-radius: 0; background: none; }
  img { width: 100%; max-width: 100%; vertical-align: middle; background: transparent !important; }

  .fancy-list { padding: 0; margin: 20px 0 0; list-style: none; font-size: var(--fz-lg); }
  .fancy-list li { position: relative; padding-left: 30px; margin-bottom: 10px; }
  .fancy-list li::before { content: '▹'; position: absolute; left: 0; color: var(--green); }

  /* Transitions */
  .fade-enter { opacity: 0; }
  .fade-enter-active { opacity: 1; transition: opacity 300ms var(--easing); }
  .fade-exit { opacity: 1; }
  .fade-exit-active { opacity: 0.5; transition: opacity 300ms var(--easing); }

  /* Scroll reveal */
  .sr-item { opacity: 0; transform: translateY(20px); transition: opacity 500ms var(--easing), transform 500ms var(--easing); }
  .sr-item.revealed { opacity: 1; transform: none; }

  /* Loader */
  .loader { display: flex; align-items: center; justify-content: center; position: fixed; top: 0; bottom: 0; left: 0; right: 0; width: 100%; height: 100%; background-color: var(--dark-navy); z-index: 99; transition: opacity 0.3s var(--easing); }
  .loader.done { opacity: 0; pointer-events: none; }
  .loader .logo-wrapper { width: 100px; }
  .loader-hex { stroke-dasharray: 280; stroke-dashoffset: 280; animation: hexDraw 0.9s ease-in-out forwards, hexFade 0.4s ease 1.0s forwards; }
  .loader-s { opacity: 0; animation: sFade 0.5s ease 0.9s forwards; }
  @keyframes hexDraw { to { stroke-dashoffset: 0; } }
  @keyframes hexFade { 0% { transform: scale(1); } 100% { transform: scale(0.95); } }
  @keyframes sFade { to { opacity: 1; } }

  /* Header */
  header { display: flex; justify-content: space-between; align-items: center; position: fixed; top: 0; z-index: 11; padding: 0 50px; width: 100%; height: var(--nav-height); background-color: #FAF9F6; filter: none !important; pointer-events: auto !important; user-select: auto !important; backdrop-filter: blur(10px); transition: var(--transition); }
  header.scrolled-up   { height: var(--nav-scroll-height); transform: translateY(0); box-shadow: 0 10px 30px -10px var(--navy-shadow); }
  header.scrolled-down { height: var(--nav-scroll-height); transform: translateY(calc(var(--nav-scroll-height) * -1)); box-shadow: 0 10px 30px -10px var(--navy-shadow); }

  .nav-logo a { color: var(--green); width: 42px; height: 42px; display: flex; align-items: center; justify-content: center; text-decoration: none; }
  .nav-logo a:hover { transform: translate(-4px,-4px); color: var(--green); }

  .nav-links { display: flex; align-items: center; }
  .nav-links ol { display: flex; align-items: center; padding: 0; margin: 0; list-style: none; counter-reset: item 0; }
  .nav-links ol li { margin: 0 10px; counter-increment: item 1; font-size: var(--fz-xs); }
  .nav-links ol li a { display: inline-block; padding: 10px; color: var(--lightest-slate); font-family: var(--font-mono); text-decoration: none; transition: var(--transition); }
  .nav-links ol li a span { display: inline-block; white-space: nowrap; transition: transform 300ms ease, color 300ms ease; }
  .nav-links ol li a:hover span { transform: translateY(-3px); color: var(--green); }
  .nav-links ol li a span::before { content: '0' counter(item) '. '; color: var(--green); font-size: var(--fz-xxs); margin-right: 2px; }

  .resume-button { color: var(--green); background: transparent; border: 1px solid var(--green); border-radius: var(--border-radius); padding: 0.75rem 1rem; font-size: var(--fz-xs); font-family: var(--font-mono); line-height: 1; text-decoration: none; transition: var(--transition); margin-left: 15px; display: inline-block; }
  .resume-button:hover, .resume-button:focus, .resume-button:active { color: var(--green); box-shadow: 3px 3px 0 0 var(--green); transform: translate(-4px,-4px); }

  /* Hamburger */
  .hamburger-btn { display: none; }
  @media (max-width: 768px) {
    .hamburger-btn { display: flex; align-items: center; justify-content: center; position: relative; z-index: 10; margin-right: -15px; padding: 15px; border: 0; background: transparent; cursor: pointer; }
  }
  .ham-box { display: inline-block; position: relative; width: var(--hamburger-width); height: 24px; }
  .ham-box-inner { position: absolute; top: 50%; right: 0; width: var(--hamburger-width); height: 2px; border-radius: var(--border-radius); background-color: var(--green); transition-duration: 0.22s; transition-property: transform; transition-timing-function: cubic-bezier(0.55,0.055,0.675,0.19); }
  .ham-box-inner.open { transform: rotate(225deg); transition-delay: 0.12s; transition-timing-function: cubic-bezier(0.215,0.61,0.355,1); }
  .ham-box-inner::before, .ham-box-inner::after { content: ''; display: block; position: absolute; left: auto; right: 0; width: var(--hamburger-width); height: 2px; border-radius: 4px; background-color: var(--green); transition-duration: 0.15s; transition-property: transform; transition-timing-function: ease; }
  .ham-box-inner::before { width: 120%; top: -10px; opacity: 1; transition: var(--ham-before); }
  .ham-box-inner.open::before { width: 100%; top: 0; opacity: 0; transition: var(--ham-before-active); }
  .ham-box-inner::after { width: 80%; bottom: -10px; transition: var(--ham-after); }
  .ham-box-inner.open::after { width: 100%; bottom: 0; transform: rotate(-90deg); transition: var(--ham-after-active); }

  /* Sidebar */
  .sidebar { display: none; }
  .menu-scrim { display: none; }
  @media (max-width: 768px) {
    .menu-scrim { display: block; position: fixed; inset: 0; background: rgba(46,46,46,0.4); z-index: 8; opacity: 0; visibility: hidden; transition: opacity 0.25s var(--easing), visibility 0.25s var(--easing); }
    .menu-scrim.open { opacity: 1; visibility: visible; }
    .sidebar { display: flex; align-items: center; justify-content: center; position: fixed; top: 0; bottom: 0; right: 0; padding: 50px 10px; width: min(75vw,400px); height: 100vh; background-color: var(--light-navy); box-shadow: -10px 0 30px -15px var(--navy-shadow); z-index: 9; transform: translateX(100vw); visibility: hidden; transition: var(--transition); }
    .sidebar.open { transform: translateX(0); visibility: visible; }
    .sidebar nav { display: flex; justify-content: space-between; align-items: center; width: 100%; flex-direction: column; color: var(--lightest-slate); font-family: var(--font-mono); text-align: center; counter-reset: item 0; }
    .sidebar nav ol { padding: 0; margin: 0; list-style: none; width: 100%; }
    .sidebar nav ol li { position: relative; margin: 0 auto 20px; counter-increment: item 1; font-size: clamp(var(--fz-sm),4vw,var(--fz-lg)); }
    .sidebar nav ol li::before { content: '0' counter(item) '.'; display: block; margin-bottom: 5px; color: var(--green); font-size: var(--fz-sm); }
    .sidebar nav ol li a { display: inline-block; text-decoration: none; color: inherit; width: 100%; padding: 3px 20px 20px; transition: var(--transition); }
    .sidebar nav ol li a:hover { color: var(--green); }
    .sidebar .resume-link { color: var(--green); background: transparent; border: 1px solid var(--green); border-radius: var(--border-radius); padding: 18px 50px; font-size: var(--fz-sm); font-family: var(--font-mono); line-height: 1; text-decoration: none; transition: var(--transition); margin: 10% auto 0; display: block; width: max-content; }
    .sidebar .resume-link:hover { box-shadow: 4px 4px 0 0 var(--green); transform: translate(-5px,-5px); color: var(--green); }
  }

  /* Side rails */
  .side-rail { width: 40px; position: fixed; bottom: 0; z-index: 10; display: flex; flex-direction: column; align-items: center; }
  .side-rail::after { content: ''; display: block; width: 1px; height: 90px; margin: 0 auto; background-color: var(--light-slate); }
  .side-rail.left  { left: 40px; }
  .side-rail.right { right: 40px; }
  .side-rail ul { display: flex; flex-direction: column; align-items: center; padding: 0; margin: 0; list-style: none; }
  .side-rail ul li:last-of-type { margin-bottom: 20px; }
  .side-rail ul li a { padding: 10px; color: var(--light-slate); display: flex; transition: var(--transition); }
  .side-rail ul li a:hover { transform: translateY(-3px); color: var(--green); }
  .side-rail ul li a svg { width: 20px; height: 20px; }
  .email-link-side { writing-mode: vertical-rl; font-family: var(--font-mono); font-size: var(--fz-xxs); letter-spacing: 0.1em; color: var(--light-slate); text-decoration: none; padding: 10px; transition: var(--transition); margin-bottom: 20px; }
  .email-link-side:hover { transform: translateY(-3px); color: var(--green); }

  /* Layout */
  main { margin: 0 auto; width: 100%; max-width: 1600px; min-height: 100vh; padding: 0 150px; counter-reset: section; }
  section { margin: 0 auto; padding: 100px 0; max-width: 1000px; }

  /* Hero */
  #hero { display: flex; flex-direction: column; align-items: flex-start; justify-content: center; min-height: 100vh; height: 100vh; padding: 0; }
  #hero::before, #hero::after { display: none !important; }
  #hero h1 { margin: 0 0 30px 4px; color: var(--green); font-family: var(--font-mono); font-size: clamp(var(--fz-sm),5vw,var(--fz-md)); font-weight: 400; }
  #hero h3 { margin-top: -10px; color: var(--light-slate); line-height: 0.9; }
  #hero p  { margin: 20px 0 0; max-width: 540px; }
  .main-button-link { color: var(--green); background: transparent; border: 1px solid var(--green); border-radius: var(--border-radius); padding: 1.25rem 1.75rem; font-size: var(--fz-sm); font-family: var(--font-mono); line-height: 1; text-decoration: none; display: inline-block; margin-top: 50px; transition: var(--transition); }
  .main-button-link:hover, .main-button-link:focus, .main-button-link:active { color: var(--green); box-shadow: 4px 4px 0 0 var(--green); transform: translate(-5px,-5px); }

  /* About */
  #about { max-width: 900px; min-height: 100vh; }
  .about-inner { display: grid; grid-template-columns: 3fr 2fr; gap: 50px; }
  .skills-list { display: grid; grid-template-columns: repeat(2,minmax(140px,200px)); gap: 0 10px; padding: 0; margin: 40px 0 0; overflow: hidden; list-style: none; }
  .skills-list li { position: relative; margin-bottom: 10px; padding-left: 20px; font-family: var(--font-mono); font-size: var(--fz-xs); }
  .skills-list li::before { content: '▹'; position: absolute; left: 0; color: var(--green); font-size: var(--fz-sm); line-height: 12px; }
  .pic-wrapper { position: relative; max-width: 300px; }
  .pic-inner { display: block; position: relative; width: 100%; border-radius: var(--border-radius); background-color: transparent; box-shadow: 0 10px 30px -15px var(--navy-shadow); transition: var(--transition); }
  .pic-inner:hover { outline: 0; transform: translate(-4px,-4px); }
  .pic-inner:hover::after { transform: translate(8px,8px); }
  .pic-inner:hover .pic-img { filter: none; }
  .pic-inner::after  { content: ''; display: block; position: absolute; width: 100%; height: 100%; border-radius: var(--border-radius); border: 2px solid var(--green); top: 14px; left: 14px; z-index: -1; transition: var(--transition); }
  .pic-img { position: relative; border-radius: var(--border-radius); filter: grayscale(40%) contrast(1); transition: var(--transition); display: block; width: 100%; }

  /* Jobs */
  #jobs { max-width: 700px; min-height: 100vh; }
  .jobs-inner { display: flex; }
  .tab-list { position: relative; z-index: 3; width: max-content; padding: 0; margin: 0; list-style: none; }
  .tab-btn { display: flex; align-items: center; width: 100%; height: var(--tab-height); padding: 0 20px 2px; border-left: 2px solid var(--lightest-navy); border-top: none; border-right: none; border-bottom: none; background: transparent; color: var(--slate); font-family: var(--font-mono); font-size: var(--fz-xs); text-align: left; white-space: nowrap; cursor: pointer; transition: var(--transition); }
  .tab-btn:hover { background-color: var(--light-navy); color: var(--green); }
  .tab-btn.active { color: var(--green); }
  .tab-highlight { position: absolute; top: 0; left: 0; z-index: 10; width: 2px; height: var(--tab-height); border-radius: var(--border-radius); background: var(--green); transition: transform 0.25s var(--easing) 0.1s; }
  .tab-panels { position: relative; width: 100%; margin-left: 20px; }
  .tab-panel { width: 100%; height: auto; padding: 10px 5px; }
  .tab-panel h3 { margin-bottom: 2px; font-size: var(--fz-xxl); font-weight: 500; line-height: 1.3; color: var(--slate); }
  .tab-panel h3 .company { color: var(--green); }
  .tab-panel .range { margin-bottom: 25px; color: var(--light-slate); font-family: var(--font-mono); font-size: var(--fz-xs); }

  /* Featured */
  .projects-grid { list-style: none; padding: 0; margin: 0; }
  .project-item { position: relative; display: grid; gap: 10px; grid-template-columns: repeat(12,1fr); align-items: center; margin-bottom: 150px; }
  .project-item:last-child { margin-bottom: 0; }
  .project-item:nth-child(odd)  .project-content { grid-column: 7/-1; text-align: right; }
  .project-item:nth-child(odd)  .project-tech-list { justify-content: flex-end; }
  .project-item:nth-child(odd)  .project-tech-list li { margin: 0 0 5px 20px; }
  .project-item:nth-child(odd)  .project-links { justify-content: flex-end; margin-left: 0; margin-right: -10px; }
  .project-item:nth-child(odd)  .project-image { grid-column: 1/8; }
  .project-item:nth-child(even) .project-content { grid-column: 1/7; }
  .project-item:nth-child(even) .project-image { grid-column: 6/-1; }
  .project-item:nth-child(even) .project-tech-list li { margin: 0 20px 5px 0; }
  .project-content { position: relative; grid-row: 1/-1; z-index: 2; }
  .project-overline { margin: 10px 0; color: var(--green); font-family: var(--font-mono); font-size: var(--fz-xs); font-weight: 400; }
  .project-title { color: #FFFFFF; font-size: clamp(24px,5vw,28px); margin: 0 0 20px; }
  .project-title a { color: inherit; }
  .project-title a:hover { color: var(--green); }
  .project-description { box-shadow: 0 10px 30px -15px var(--navy-shadow); position: relative; z-index: 2; padding: 25px; border-radius: var(--border-radius); background-color: #000000; opacity: 1; color: #FFFFFF; font-size: var(--fz-lg); transition: box-shadow 0.25s var(--easing); }
  .project-description a { color: var(--green); }
  .project-description:hover { box-shadow: 0 20px 30px -15px var(--navy-shadow); }
  .project-tech-list { display: flex; flex-wrap: wrap; position: relative; z-index: 2; margin: 25px 0 10px; padding: 0; list-style: none; }
  .project-tech-list li { color: var(--lightest-slate); font-family: var(--font-mono); font-size: var(--fz-xs); white-space: nowrap; margin-bottom: 5px; }
  .project-links { display: flex; align-items: center; position: relative; margin-top: 10px; margin-left: -10px; color: var(--lightest-slate); }
  .project-links a { padding: 10px; color: var(--lightest-slate); transition: var(--transition); }
  .project-links a:hover { color: var(--green); transform: translateY(-3px); }
  .project-links a svg { width: 20px; height: 20px; }
  .project-links a.external svg { width: 22px; height: 22px; }
  .project-image { box-shadow: 0 10px 30px -15px var(--navy-shadow); grid-row: 1/-1; position: relative; z-index: 1; transition: box-shadow 0.25s var(--easing); }
  .project-image:hover { box-shadow: 0 20px 30px -15px var(--navy-shadow); }
  .project-image a { display: block; width: 100%; height: 100%; background-color: #2E2E2E; border-radius: var(--border-radius); }
  .project-image a:hover .proj-img { filter: none; mix-blend-mode: normal; }
  .proj-img { border-radius: var(--border-radius); mix-blend-mode: multiply; filter: grayscale(100%) contrast(1) brightness(90%); transition: var(--transition); display: block; width: 100%; }

  /* Logo slider */
  #logos { max-width: 1000px; margin: 0 auto; padding: 100px 0; }
  .logo-slider-wrap { padding: 2rem 0; overflow: hidden; position: relative; }
  .logo-track { display: flex; gap: 30px; animation: logoScroll 90s linear infinite; width: max-content; }
  .logo-track:hover { animation-play-state: paused; }
  @keyframes logoScroll { from { transform: translateX(0); } to { transform: translateX(-50%); } }
  .logo-slide { flex: 0 0 auto; display: flex; align-items: center; justify-content: center; width: 140px; }
  .logo-slide img { height: 80px; width: auto; max-width: 100%; object-fit: contain; filter: grayscale(100%) opacity(0.4); transition: filter 0.3s ease; }
  .logo-slide img:hover { filter: grayscale(0%) opacity(1); }

  /* Contact */
  #contact { max-width: 600px; min-height: 100vh; margin: 0 auto 100px; text-align: center; display: flex; flex-direction: column; justify-content: center; align-items: center; }
  .contact-overline { display: block; margin-bottom: 20px; color: var(--green); font-family: var(--font-mono); font-size: var(--fz-md); font-weight: 400; }
  .contact-title { font-size: clamp(40px,5vw,60px); margin-bottom: 20px; }
  .email-cta { color: var(--green); background: transparent; border: 1px solid var(--green); border-radius: var(--border-radius); padding: 1.25rem 1.75rem; font-size: var(--fz-sm); font-family: var(--font-mono); line-height: 1; text-decoration: none; transition: var(--transition); margin-top: 50px; display: inline-block; }
  .email-cta:hover, .email-cta:focus, .email-cta:active { color: var(--green); box-shadow: 4px 4px 0 0 var(--green); transform: translate(-5px,-5px); }

  /* Footer */
  footer { display: flex; flex-direction: column; align-items: center; justify-content: center; height: auto; min-height: 70px; padding: 15px; text-align: center; }
  .footer-address { margin-top: 20px; font-family: var(--font-mono); font-size: var(--fz-xxs); color: var(--light-slate); }
  .footer-address a { color: var(--light-slate); }
  .footer-address a:hover { color: var(--green); text-decoration: underline; }

  /* Responsive */
  @media (max-width: 1080px) { header { padding: 0 40px; } main { padding: 0 100px; } .numbered-heading::after { width: 200px; } }
  @media (max-width: 768px) {
    header { padding: 0 25px; }
    .nav-links { display: none; }
    .side-rail { display: none; }
    main { padding: 150px 50px; }
    .about-inner { display: block; }
    .pic-wrapper { margin: 50px auto 0; width: 70%; }
    .jobs-inner { display: block; }
    .tab-list { display: flex; flex-wrap: wrap; width: 100%; padding-left: 0; margin-left: 0; margin-bottom: 30px; }
    .tab-list::-webkit-scrollbar { display: none; }
    .tab-btn { flex: 1 1 auto; border-left: none; border-bottom: 2px solid var(--lightest-navy); min-width: 0; justify-content: center; padding: 0 12px; }
    .tab-btn.active { border-bottom-color: var(--green); }
    .tab-highlight { display: none; }
    .tab-panels { margin-left: 0; }
    .project-item { display: block; box-shadow: 0 10px 30px -15px var(--navy-shadow); margin-bottom: 70px; position: relative; overflow: hidden; }
    .project-content { padding: 40px 40px 30px; text-align: left !important; position: relative; z-index: 5; }
    .project-tech-list { justify-content: flex-start !important; margin: 10px 0; }
    .project-tech-list li { margin: 0 10px 5px 0 !important; color: var(--lightest-slate); }
    .project-links { justify-content: flex-start !important; margin-left: -10px !important; margin-right: 0 !important; }
    .project-image { position: absolute; top: 0; left: 0; width: 100%; height: 100%; opacity: 0.25; }
    .proj-img { object-fit: cover; width: 100%; height: 100%; filter: grayscale(100%) contrast(1) brightness(50%); }
    .project-title { color: var(--white); }
    .numbered-heading::after { width: 100%; }
    #hero { height: auto; padding-top: var(--nav-height); min-height: 100vh; }
  }
  @media (max-width: 600px) { .tab-list { width: 100%; padding-left: 0; margin-left: 0; } }
  @media (max-width: 480px) { main { padding: 125px 25px; } body { font-size: var(--fz-lg); } #hero h1 { margin: 0 0 20px 2px; } .project-content { padding: 25px 25px 20px; } #contact { margin: 0 auto 50px; } }
  @media (max-height: 700px) and (min-width: 700px) { #hero { height: auto; padding-top: var(--nav-height); } }
  @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; } }
`;

