// ─── ScrambledText ──────────────────────────────────────────────────────────
function ScrambledText({ text, as: Tag = 'span', ...props }) {
  const ref = useRef(null); const animId = useRef(null); const going = useRef(false);
  const go = useCallback(() => {
    const el = ref.current; if (!el) return;
    const chars = text.split(''); let t0 = null; const dur = 800;
    const step = (ts) => {
      if (!t0) t0 = ts; const p = ts - t0;
      if (p >= dur) { el.innerText = text; going.current = false; return; }
      const idx = Math.floor((p/dur)*chars.length);
      el.innerText = chars.map((c,i) => (i<=idx||c===' ')?c:String.fromCharCode(Math.floor(Math.random()*94)+33)).join('');
      animId.current = requestAnimationFrame(step);
    };
    animId.current = requestAnimationFrame(step);
  }, [text]);
  const onEnter = () => { if (!going.current) { going.current=true; go(); } };
  const onLeave = () => { cancelAnimationFrame(animId.current); if (ref.current) ref.current.innerText=text; going.current=false; };
  return <Tag ref={ref} onMouseEnter={onEnter} onMouseLeave={onLeave} {...props}>{text}</Tag>;
}

// ─── Hooks ──────────────────────────────────────────────────────────────────
function useScrollReveal(delay=0) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    el.classList.add('sr-item');
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setTimeout(()=>el.classList.add('revealed'),delay); obs.disconnect(); } }, {threshold:0.1});
    obs.observe(el); return ()=>obs.disconnect();
  }, [delay]);
  return ref;
}
function useScrollDirection() {
  const [dir,setDir]=useState('none'); const [atTop,setAtTop]=useState(true);
  useEffect(()=>{
    let prev=window.scrollY;
    const fn=()=>{ const y=window.scrollY; setAtTop(y<50); setDir(y>prev?'down':'up'); prev=y; };
    window.addEventListener('scroll',fn,{passive:true}); return ()=>window.removeEventListener('scroll',fn);
  },[]);
  return {dir,atTop};
}

// ─── Loader ─────────────────────────────────────────────────────────────────
function Loader({ onDone }) {
  useEffect(()=>{ const t=setTimeout(onDone,2000); return ()=>clearTimeout(t); },[onDone]);
  return (
    <div className="loader">
      <div className="logo-wrapper">
        <svg xmlns="http://www.w3.org/2000/svg" role="img" viewBox="0 0 84 96" style={{width:100,height:100,fill:'none'}}>
          <polygon className="loader-hex" points="42 3 79 22 79 74 42 93 5 74 5 22" stroke="var(--green)" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round"/>
          <text className="loader-s" x="50%" y="50%" dominantBaseline="central" textAnchor="middle" style={{fill:'var(--green)',fontFamily:'var(--font-mono)',fontSize:32,fontWeight:600,stroke:'none'}}>S</text>
        </svg>
      </div>
    </div>
  );
}

// ─── Menu ───────────────────────────────────────────────────────────────────
function Menu() {
  const [open,setOpen]=useState(false);
  const wrap=useRef(null);
  useEffect(()=>{
    const onKey=(e)=>{ if(e.key==='Escape') setOpen(false); };
    const onResize=()=>{ if(window.innerWidth>768) setOpen(false); };
    const onOut=(e)=>{ if(wrap.current&&!wrap.current.contains(e.target)) setOpen(false); };
    document.addEventListener('keydown',onKey); window.addEventListener('resize',onResize); document.addEventListener('mousedown',onOut);
    return ()=>{ document.removeEventListener('keydown',onKey); window.removeEventListener('resize',onResize); document.removeEventListener('mousedown',onOut); };
  },[]);
  useEffect(()=>{ document.body.classList.toggle('hidden',open); return ()=>document.body.classList.remove('hidden'); },[open]);
  return (
    <div ref={wrap}>
      <button className="hamburger-btn" onClick={()=>setOpen(o=>!o)} aria-label="Menu">
        <div className="ham-box"><div className={`ham-box-inner${open?' open':''}`}/></div>
      </button>
      <div className={`menu-scrim${open?' open':''}`} onClick={()=>setOpen(false)} aria-hidden="true"></div>
      <aside className={`sidebar${open?' open':''}`} aria-hidden={!open} tabIndex={open?1:-1}>
        <nav>
          <ol>
            {NAV_LINKS.map(({name,url})=>(
              <li key={name}><a href={url} onClick={()=>setOpen(false)}>{name}</a></li>
            ))}
          </ol>
          <a href="https://stenbossong.nl/resume.pdf" className="resume-link" target="_blank" rel="noreferrer">Resume</a>
        </nav>
      </aside>
    </div>
  );
}

// ─── Nav ────────────────────────────────────────────────────────────────────
function Nav({ mounted }) {
  const {dir,atTop}=useScrollDirection();
  const cls = !atTop&&dir==='up'?'scrolled-up':!atTop&&dir==='down'?'scrolled-down':'';
  return (
    <header className={cls}>
      <div className="nav-logo"><a href="/" aria-label="home"><IconHex/></a></div>
      <div className="nav-links" style={{opacity:mounted?1:0,transition:'opacity 0.3s ease 0.3s'}}>
        <ol>{NAV_LINKS.map(({name,url})=>(<li key={name}><a href={url}><span>{name}</span></a></li>))}</ol>
        <a className="resume-button" href="https://stenbossong.nl/resume.pdf" target="_blank" rel="noreferrer">Download CV</a>
      </div>
      <Menu/>
    </header>
  );
}

