// ─── About ──────────────────────────────────────────────────────────────────
function About() {
  const ref=useScrollReveal(); const [age,setAge]=useState(null);
  useEffect(()=>{ const b=new Date(1992,0,15),n=new Date(); let a=n.getFullYear()-b.getFullYear(); if(n.getMonth()<b.getMonth()||(n.getMonth()===b.getMonth()&&n.getDate()<b.getDate()))a--; setAge(a); },[]);
  return (
    <section id="about" ref={ref}>
      <h2 className="numbered-heading">Over mij</h2>
      <div className="about-inner">
        <div>
          <p>{age!==null?`Ik ben ${age} jaar oud, `:''}marketeer met een passie voor innovatie, groei en performance. Geboren en getogen in Amstelveen.</p>
          <p>Welkom bij mijn portfolio. Ik begon mijn reis als consultant bij een <a className="inline-link" href="https://imlounge.nl" target="_blank" rel="noreferrer">mediabureau</a>, werd performance marketeer voor <a className="inline-link" href="https://beyonddutch.nl" target="_blank" rel="noreferrer">een internationale scale-up</a> en was CMO van een <a className="inline-link" href="https://bikefair.org" target="_blank" rel="noreferrer">digitale marktplaats</a>.</p>
          <p>Vandaag help ik merken via mijn eigen bureau <a className="inline-link" href="https://flii.nl" target="_blank" rel="noreferrer">Flii Media</a>, samen met een vertrouwd netwerk aan freelancers.</p>
          <ul className="skills-list">{SKILLS.map((s,i)=>(<li key={i}><ScrambledText text={s}/></li>))}</ul>
        </div>
        <div className="pic-wrapper">
          <a className="pic-inner" href="https://linkedin.com/in/sten-bossong" target="_blank" rel="noreferrer">
            <img className="pic-img" src={IMG_ME} alt="Sten Bossong"/>
          </a>
        </div>
      </div>
    </section>
  );
}

// ─── Jobs ───────────────────────────────────────────────────────────────────
function Jobs() {
  const ref=useScrollReveal(); const [active,setActive]=useState(0);
  return (
    <section id="jobs" ref={ref}>
      <h2 className="numbered-heading">Ervaring</h2>
      <div className="jobs-inner">
        <div style={{position:'relative'}}>
          <div className="tab-list" role="tablist">
            {JOBS.map((j,i)=>(<button key={j.company} className={`tab-btn${active===i?' active':''}`} role="tab" aria-selected={active===i} onClick={()=>setActive(i)} tabIndex={active===i?0:-1}>{j.company}</button>))}
            <div className="tab-highlight" style={{transform:`translateY(calc(${active} * var(--tab-height)))`}}/>
          </div>
        </div>
        <div className="tab-panels">
          {JOBS.map((j,i)=>(
            <div key={j.company} className="tab-panel" role="tabpanel" hidden={active!==i} style={{display:active!==i?'none':'block'}}>
              <h3><span>{j.title}</span><span className="company">&nbsp;@&nbsp;<a className="inline-link" href={j.url} target="_blank" rel="noreferrer">{j.company}</a></span></h3>
              <p className="range">{j.range}</p>
              <div dangerouslySetInnerHTML={{__html:j.html.replace(/<ul>/g,'<ul class="fancy-list">')}}/>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

// ─── Logo slider ────────────────────────────────────────────────────────────
function LogoSlider() {
  const doubled = [...LOGOS, ...LOGOS];
  return (
    <section id="logos">
      <div className="logo-slider-wrap">
        <div className="logo-track">
          {doubled.map((src,i)=>(<div className="logo-slide" key={i}><img src={src} alt={`Client logo ${(i%LOGOS.length)+1}`}/></div>))}
        </div>
      </div>
    </section>
  );
}

// ─── Featured ───────────────────────────────────────────────────────────────
function Featured() {
  const titleRef=useScrollReveal();
  const r0=useScrollReveal(0), r1=useScrollReveal(100), r2=useScrollReveal(200);
  const refs=[r0,r1,r2];
  return (
    <section id="featured">
      <h2 className="numbered-heading" ref={titleRef}>Uitgelicht</h2>
      <ul className="projects-grid">
        {FEATURED.map((p,i)=>(
          <li className="project-item" key={p.title} ref={refs[i]}>
            <div className="project-content">
              <p className="project-overline">Featured Project</p>
              <h3 className="project-title"><a href={p.external} target="_blank" rel="noreferrer">{p.title}</a></h3>
              <div className="project-description" dangerouslySetInnerHTML={{__html:p.html}}/>
              <ul className="project-tech-list">{p.tech.map((t,ti)=>(<li key={ti}><ScrambledText text={t}/></li>))}</ul>
              <div className="project-links"><a href={p.external} aria-label="External Link" className="external" target="_blank" rel="noreferrer"><IconExternal/></a></div>
            </div>
            <div className="project-image"><a href={p.external} target="_blank" rel="noreferrer"><img src={p.img} alt={p.title} className="proj-img"/></a></div>
          </li>
        ))}
      </ul>
    </section>
  );
}

// ─── Contact ────────────────────────────────────────────────────────────────
function Contact() {
  const ref=useScrollReveal();
  return (
    <section id="contact" ref={ref}>
      <h2 className="numbered-heading overline" style={{display:'block',textAlign:'center',whiteSpace:'normal'}}>
        <span className="contact-overline">What's next?</span>
      </h2>
      <h2 className="contact-title">Let's ignite ambitions</h2>
      <p>Stuur een postduif, mail naar <a className="inline-link" href={`mailto:${EMAIL}`}>{EMAIL}</a> of <a className="inline-link" href="https://maps.app.goo.gl/81u3kVTVq13E6AiB6" target="_blank" rel="noreferrer">kom langs op kantoor</a> in Amstelveen.</p>
      <a className="email-cta" href={`mailto:${EMAIL}`}>Contact</a>
    </section>
  );
}

// ─── Footer ─────────────────────────────────────────────────────────────────
function Footer() {
  return (
    <footer>
      <div className="footer-address">
        <a href="https://maps.app.goo.gl/LaAfTHWacT738dAJ6" target="_blank" rel="noreferrer">[ 52.29'N / 4.85'O ]</a>
      </div>
    </footer>
  );
}

// ─── App ────────────────────────────────────────────────────────────────────
export default function App() {
  const [loading,setLoading]=useState(true);
  const [mounted,setMounted]=useState(false);
  const done=useCallback(()=>{ setLoading(false); setTimeout(()=>setMounted(true),100); },[]);
  return (
    <>
      <style>{FONT_FACES + BASE_CSS}</style>
      {loading && <Loader onDone={done}/>}
      <Nav mounted={mounted}/>
      <Social mounted={mounted}/>
      <EmailRail mounted={mounted}/>
      <div id="content">
        <main className="fillHeight">
          <Hero mounted={mounted}/>
          <About/>
          <Jobs/>
          <LogoSlider/>
          <Featured/>
          <Contact/>
        </main>
        <Footer/>
      </div>
    </>
  );
}
